 if(!latest?.success){const r={success:false,analysisEnabled:false,issues:["ابتدا یک حالت بار جرثقیل را در قاب سه‌بعدی تحلیل کنید."]};if(host)host.textContent=JSON.stringify(r,null,2);return r;}
