    coords.forEach(p=>{const cx=x0+pad+8+(maxX===minX?0:(p.xMm-minX)/(maxX-minX)*(w-2*pad-16)),cy=y0+pad+8+(maxY===minY?0:(p.yMm-minY)/(maxY-minY)*(h-2*pad-16));svg.push('<circle cx="'+cx+'" cy="'+cy+'" r="6" fill="#dc2626"/>');});
