 test("reject-missing-support-stiffness",()=>{try{analyze({...base,supports:[{x_m:0,kVertical_N_m:0},{x_m:10,kVertical_N_m:1e12}]});return false;}catch(e){return String(e.message).includes("مثبت");}});
