   const cm=Array.isArray(c.members)?c.members:[],byId=new Map();
   cm.forEach(x=>{const id=String(x.id||"");if(!id||byId.has(id))issues.push("شناسه عضو در ترکیب "+label+" خالی یا تکراری است.");else byId.set(id,x);});
