 const duplicateCaseLabels=[...new Set(caseLabels.filter((label,i)=>label&&caseLabels.indexOf(label)!==i))];
 const expectedLabels=Array.isArray(expectedCaseLabels)?expectedCaseLabels.map(x=>String(x??"").trim()):null;
