  if(!(Number(mat.Fu)>0))local.push("Fu معتبر گروه عضو در ورودی مصالح موجود نیست.");
  const demandBridge=extractGroupTensionDemand(g),manualDemand=Number(d.forceDemandKN)>0?Number(d.forceDemandKN):null;
