  const d=data.groups[g]||{};
  const fields=FIELDS.map(([k,caption])=>'<div class="field"><label for="tension_'+g+'_'+k+'">'+caption+'</label><input type="number" step="any" id="tension_'+g+'_'+k+'" value="'+(d[k]??"")+'"></div>').join("");
