  ids.add(id);
  const entries=Array.isArray(m?.ends)?m.ends:[];
  if(!entries.length){issues.push("برای عضو "+(id||"بدون شناسه")+" هیچ بردار نیروی انتهایی ثبت نشده است.");return;}
  const labels=new Set();
