 const b={nodes:[{id:"A",x:0,y:0,z:0},{id:"B",x:2.01,y:0,z:0},{id:"C",x:4,y:0,z:0}],members:[{id:"M",start:"B",end:"A",sectionRef:"S2"},{id:"N",start:"A",end:"C",sectionRef:"S3"}]};
